/* Hallmark · pre-emit critique: P4 H4 E4 S5 R5 V4. */
(function(root){
  'use strict';
  var escape=function(value){return String(value).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});};
  function random(s){s.rng=(Math.imul(s.rng,1664525)+1013904223)>>>0;return s.rng/4294967296;}
  function shuffle(s,items){var a=items.slice();for(var i=a.length-1;i>0;i--){var j=Math.floor(random(s)*(i+1)),v=a[i];a[i]=a[j];a[j]=v;}return a;}
  function integer(n,min,max){return Number.isInteger(n)&&n>=min&&n<=max;}
  function button(action,label,disabled,extra){return '<button type="button" data-campaign-action="'+action+'" '+(disabled?'disabled ':'')+(extra||'')+'>'+escape(label)+'</button>';}
  function mount(id,key,engine,view,options){
    var host=root.document&&root.document.getElementById(id);if(!host)return null;options=options||{};
    var state=null,revision=0,warning='',rejected=null,lastSaved=null,expectedRaw=null,restartPending=false,meta={runs:0,clears:0,best:0};
    function decode(raw){try{var v=JSON.parse(raw);return v&&v.schema===1&&integer(v.revision,1,1e9)&&v.meta&&['runs','clears','best'].every(function(k){return integer(v.meta[k],0,1e9);})&&engine.valid(v.state)?v:null;}catch(e){return null;}}
    try{var raw=root.localStorage.getItem(key),found=decode(raw);expectedRaw=raw;if(raw&&!found){rejected=raw;found=decode(root.localStorage.getItem(key+'.backup'));warning=found?'已恢复上一份有效存档。':'进度暂时无法读取，原内容会保留。';}if(found){state=found.state;revision=found.revision;meta=found.meta;lastSaved=JSON.stringify(found);if(options.realtime)state.paused=true;}}catch(e){warning='本地存储不可用，本页仍可游玩。';}
    function showWarning(){var node=host.querySelector('[data-campaign-storage]');if(node){node.textContent=warning;node.hidden=!warning;}}
    function save(){if(!state)return false;try{if(root.localStorage.getItem(key)!==expectedRaw){warning='另一页面已更新本局。本页操作未写入存档；刷新可读取新进度。';showWarning();return false;}if(rejected!==null){root.localStorage.setItem(key+'.rejected',rejected);if(root.localStorage.getItem(key+'.rejected')!==rejected)throw new Error('preserve');rejected=null;}var next=JSON.stringify({schema:1,revision:revision+1,meta:meta,state:state});if(!decode(next))throw new Error('invalid');root.localStorage.setItem(key+'.pending',next);if(root.localStorage.getItem(key+'.pending')!==next)throw new Error('verify');if(lastSaved&&decode(lastSaved))root.localStorage.setItem(key+'.backup',lastSaved);root.localStorage.setItem(key,next);if(root.localStorage.getItem(key)!==next)throw new Error('verify');root.localStorage.removeItem(key+'.pending');revision++;lastSaved=next;expectedRaw=next;warning='';showWarning();return true;}catch(e){warning='本次进度未保存；刷新前请保留此页。';showWarning();return false;}}
    function settle(){if(state&&(state.phase==='won'||state.phase==='lost'||state.phase==='extracted')&&!state.recorded){state.recorded=true;meta.best=Math.max(meta.best,engine.score(state));if(state.phase==='won'||state.phase==='extracted'&&engine.score(state)>0)meta.clears++;}}
    function render(){host.innerHTML='<p class="campaignWarning" data-campaign-storage role="alert" '+(!warning?'hidden':'')+'>'+escape(warning)+'</p>'+(restartPending?view(null,meta,'')+'<p class="campaignWarning">选择新方案会重新开局，已完成的记录保留。</p>'+button('cancelRestart','继续本局'):view(state,meta,'')+(state&&['won','lost','extracted'].indexOf(state.phase)<0?'<div class="campaignToolbar">'+button('restartPrompt','更换方案')+'</div>':''));if(options.draw&&state&&!restartPending)options.draw(host,state);}
    host.addEventListener('click',function(event){var node=event.target.closest('[data-campaign-action]');if(node&&node.disabled)return;var data=node?node.dataset:state&&!restartPending&&options.pointer?options.pointer(host,state,event):null;if(!data)return;var action=data.campaignAction;if(action==='restartPrompt'){restartPending=true;if(options.realtime){state.paused=true;save();}render();return;}if(action==='cancelRestart'){restartPending=false;render();return;}if(action==='start'){if(state&&!restartPending&&['won','lost','extracted'].indexOf(state.phase)<0)return;state=engine.create((Date.now()^Math.floor(Math.random()*0xffffffff))>>>0,data.choice||'');restartPending=false;meta.runs++;}else if(!state||!engine.act(state,action,data))return;settle();save();render();var selector='[data-campaign-action="'+action+'"]';['site','cell','card','item','enemy','choice'].forEach(function(k){var value=data[k];if(value!==undefined&&/^[\w-]+$/.test(value))selector+='[data-'+k+'="'+value+'"]';});var focus=host.querySelector(selector);if(!focus||focus.disabled)focus=host.querySelector('[data-campaign-action]:not([disabled])');if(focus)focus.focus({preventScroll:true});});
    if(options.realtime){var last=0,savedTime=0;function frame(time){var dt=last?Math.min(.15,Math.max(0,(time-last)/1000)):0;last=time;if(state&&state.phase==='wave'&&!state.paused){if(root.document.hidden||!host.getClientRects().length){state.paused=true;save();render();}else{var phase=state.phase;engine.tick(state,dt);settle();savedTime+=dt;if(state.phase!==phase){save();render();}else{if(options.draw)options.draw(host,state);if(options.live)options.live(host,state);if(savedTime>=3){save();savedTime=0;}}}}root.requestAnimationFrame(frame);}root.requestAnimationFrame(frame);function pauseActive(){if(state&&state.phase==='wave'&&!state.paused){state.paused=true;save();render();}}root.addEventListener('pagehide',pauseActive);root.document.addEventListener('visibilitychange',function(){if(root.document.hidden)pauseActive();});root.addEventListener('hashchange',pauseActive);}
    render();return{save:save,render:render};
  }
  root.XXSXCampaignCore={escape:escape,random:random,shuffle:shuffle,integer:integer,button:button,mount:mount};
})(window);
